frappe.ui.form.on('Sabre Sales Opportunity', {
    
    refresh(frm) {
        // تنظيف الأزرار المخصصة عند عمل refresh لمنع تكرار الأزرار
        frm.clear_custom_buttons();

        if (frm.doc.opportunity_type) {
            frm.trigger('opportunity_type');
        }

        // التحقق أن المستند تم حفظه وليس مسودة جديدة
        if (!frm.is_new()) {
            
            // 1️⃣ خط الدفاع الأول: جلب الحالة الحقيقية من السيرفر فوراً لمنع الكاش القديم
            frappe.db.get_value('Sabre Sales Opportunity', frm.doc.name, 'workflow_state', (r) => {
                
                if (r && r.workflow_state !== frm.doc.workflow_state) {
                    // إذا تغيرت الحالة في الخلفية، حدّث الصفحة بأكملها فوراً تلقائياً
                    frm.reload_doc();
                } else {
                    // 2️⃣ إذا كانت البيانات محدثة ومطابقة، ارسم الأزرار بناءً على الحالة الصحيحة والصلاحيات
                    
                    // 🟢 الحالة الأولى: Qualification (كودك القديم كما هو)
                    if (frm.doc.workflow_state === 'Qualification') {
                        
                        if (frappe.user.has_role('Sabre Account Manager') || frappe.user.has_role('System Manager') || frappe.user.has_role('Administrator')) {
                            
                            frappe.db.get_value('Sabre Qualification Checklist', {opportunity: frm.doc.name}, 'name', (res) => {
                                if (res && res.name) {
                                    frm.add_custom_button(' View Qualification Checklist ', () => {
                                        frappe.set_route('Form', 'Sabre Qualification Checklist', res.name);
                                    }).addClass('btn-primary');
                                } else {
                                    frm.add_custom_button(' Create Qualification Checklist', () => {
                                        frappe.new_doc('Sabre Qualification Checklist', {
                                            opportunity: frm.doc.name
                                        });
                                    }).addClass('btn-primary');
                                }
                            });
                        }
                    } 
                    
                    // 🟡 الحالة الثانية: Business Case (كودك القديم كما هو)
                    else if (frm.doc.workflow_state === 'Business Case' || frm.doc.workflow_state === 'BC') {
                        
                        if (frappe.user.has_role('Sabre Account Manager') || frappe.user.has_role('System Manager') || frappe.user.has_role('Administrator')) {
                            
                            frappe.db.get_value('Sabre Business Case', {opportunity: frm.doc.name}, 'name', (res) => {
                                if (res && res.name) {
                                    frm.add_custom_button(' Create Another Business Case', () => {
                                        frappe.new_doc('Sabre Business Case', {
                                            opportunity: frm.doc.name
                                        });
                                    }).addClass('btn-primary');
                                } else {
                                    frm.add_custom_button(' Create Business Case', () => {
                                        frappe.new_doc('Sabre Business Case', {
                                            opportunity: frm.doc.name
                                        });
                                    }).addClass('btn-primary');
                                }
                            });
                        }
                    } // نهاية شرط الـ Business Case
                    
                    // 🔵 الحالة الثالثة: Contract Preparation (تعديل لتمرير البيانات مباشرة)
                    else if (frm.doc.workflow_state === 'Contract Preparation') {
                        
                        if (frappe.user.has_role('Sabre Account Manager') || frappe.user.has_role('System Manager') || frappe.user.has_role('Administrator')) {
                            
                            frm.add_custom_button(__('Create Contract'), () => {
                                // استخدام دالة new_doc السريعة وتمرير كافة البيانات للنموذج الجديد فوراً
                                frappe.new_doc('Sabre Contract', {
                                    opportunity: frm.doc.name,
                                                       customer: frm.doc.customer,
                                    pipeline_am: frm.doc.pipeline_am // تمرير الـ AM مباشرة
                                });
                            }).addClass('btn-primary');
                        }
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Sabre Qualification Checklist', {

    // عند فتح الفورم أو تحديثه
    refresh(frm) {
        frm.toggle_display('reason_code', false);
        if (frm.doc.qualified) {
            frm.trigger('qualified');
        }

        // 🛑 التعديل المصلح: جلب حالة الـ Workflow من الـ Opportunity المرتبطة وليس من الـ Checklist
        if (!frm.is_new() && frm.doc.opportunity) {
            // التحقق من صلاحية المستخدم (Account Manager أو مدير نظام)
            if (frappe.user.has_role('Sabre Account Manager') || frappe.user.has_role('System Manager') || frappe.user.has_role('Administrator')) {
                
                // هنا نطلب الحالة من جدول الـ Sales Opportunity باستخدام رقم الفرصة المخزن في النموذج الحالي
                frappe.db.get_value('Sabre Sales Opportunity', frm.doc.opportunity, 'workflow_state', (r) => {
                    
                    // الشرط: إذا كانت هذه الـ Checklist مقبولة (Yes) وحالة الفرصة في السيرفر أصبحت Business Case
                    if (frm.doc.qualified === 'Yes' && r && r.workflow_state === 'Business Case') {
                        
                        // التحقق هل تم إنشاء Business Case مسبقاً لهذه الفرصة؟
                        frappe.db.get_value('Sabre Business Case', {opportunity: frm.doc.opportunity}, 'name', (res) => {
                            if (res && res.name) {
                                // السيناريو أ: الـ Business Case موجودة مسبقاً
                                // frm.add_custom_button('👁️ عرض Business Case', () => {
                                //     frappe.set_route('Form', 'Sabre Business Case', res.name);
                                // }).addClass('btn-primary');
                                frm.add_custom_button('📋 إنشاء Another Business Case', () => {
                                    frappe.new_doc('Sabre Business Case', {
                                        opportunity: frm.doc.opportunity
                                    });
                                }).addClass('btn-primary');
                            } else {
                                // السيناريو ب: الـ Business Case غير موجودة
                                frm.add_custom_button('📋 إنشاء Business Case', () => {
                                    frappe.new_doc('Sabre Business Case', {
                                        opportunity: frm.doc.opportunity
                                    });
                                }).addClass('btn-primary');
                            }
                        });

                    }
                });
            }
        }
    },

    // عند اختيار الـ Opportunity (الأكواد القديمة كما هي بدون تغيير)
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am', 'yoy_review', 'total_gds_volume','airline_mix'],
                (data) => {
                    if (data) {
                        frm.set_value('ttm_volume', data.total_gds_volume);
                        frm.set_value('yoy_growth', data.yoy_review);
                        frm.set_value('airline_mix', data.airline_mix);
                    }
                }
            );
        }
    },

    // عند تغيير نتيجة التأهيل (الأكواد القديمة كما هي بدون تغيير)
    qualified(frm) {
        if (frm.doc.qualified === 'No') {
            frm.toggle_display('reason_code', true);
            frm.set_df_property('reason_code', 'reqd', 1);
        } else {
            frm.toggle_display('reason_code', false);
            frm.set_df_property('reason_code', 'reqd', 0);
            frm.set_value('reason_code', '');
        }
    }

});

frappe.ui.form.on('Sabre Business Case', {

    // عند فتح الفورم
    refresh(frm) {
        frm.toggle_display('head_of_sales_notes', false);

        if (frm.doc.status) {
            frm.trigger('status');
        }
    },

    // جلب بيانات الـ Opportunity تلقائياً
    opportunity(frm) {
    if (frm.doc.opportunity) {
        frappe.db.get_value(
            'Sabre Sales Opportunity',
            frm.doc.opportunity,
            ['customer', 'pipeline_am', 'airline_mix', 'yoy_review'],
            (data) => {
                if (data) {
                    frm.set_value('customer', data.customer);
                    frm.set_value('pipeline_am', data.pipeline_am);
                    frm.set_value('airline_mix', data.airline_mix);
                    frm.set_value('yoy_review', data.yoy_review);
                }
            }
        );
    }
},

    // إظهار Head of Sales Notes عند Rejected فقط
    status(frm) {
        if (frm.doc.status === 'Rejected') {
            frm.toggle_display('head_of_sales_notes', true);
            frm.set_df_property('head_of_sales_notes', 'reqd', 1);
        } else {
            frm.toggle_display('head_of_sales_notes', false);
            frm.set_df_property('head_of_sales_notes', 'reqd', 0);
        }
    }

});

frappe.ui.form.on('Sabre Contract', {

    // عند فتح الفورم
    refresh(frm) {
        frm.toggle_display('notes', false);

        if (frm.doc.head_of_sales_review) {
            frm.trigger('head_of_sales_review');
        }
    },

    // جلب بيانات الـ Opportunity تلقائياً
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frm.set_value('customer', data.customer);
                        frm.set_value('pipeline_am', data.pipeline_am);
                    }
                }
            );
        }
    },

    // إظهار Notes عند Rejected فقط
    head_of_sales_review(frm) {
        if (frm.doc.head_of_sales_review === 'Rejected') {
            frm.toggle_display('notes', true);
            frm.set_df_property('notes', 'reqd', 1);
        } else {
            frm.toggle_display('notes', false);
            frm.set_df_property('notes', 'reqd', 0);
        }
    }

});

frappe.ui.form.on('Sabre Implementation', {

    // عند فتح الفورم
    refresh(frm) {
        // إظهار زر إنشاء Ticket تلقائياً إذا لم تكن هناك تيكت مرتبطة والمستند ليس جديداً
        if (!frm.doc.ticket_number && !frm.is_new()) {
            frm.add_custom_button('إنشاء Ticket', () => {
                
                frappe.prompt(
                    [
                        { label: 'عنوان الـ Ticket (Subject)', fieldname: 'subject', fieldtype: 'Data', reqd: 1 },
                        { label: 'التفاصيل / الوصف', fieldname: 'description', fieldtype: 'Small Text' }
                    ],
                    (values) => {
                        
                        // 🟢 إنشاء التيكت وتوجيه البيانات للحقل الجديد pcc
                        frappe.db.insert({
                            doctype: 'HD Ticket',
                            subject: values.subject,
                            description: values.description,
                            pcc: frm.doc.customer,         // 🌟 التعديل هنا: إرسال القيمة لحقل pcc بدلاً من customer
                            opportunity: frm.doc.opportunity,  // ربط التيكت بنفس الفرصة تلقائياً
                            status: 'Open'
                        }).then(inserted_ticket => {
                            
                            // بعد نجاح الإنشاء، نأخذ الرقم الفعلي التلقائي الذي ولده السيستم
                            frm.set_value('ticket_number', inserted_ticket.name);
                            frm.save(); // حفظ صفحة الـ Implementation بالرقم الجديد
                            
                            frappe.show_alert({
                                message: `✅ تم إنشاء التيكت بنجاح في النظام برقم: ${inserted_ticket.name}`,
                                indicator: 'green'
                            });
                        }).catch(err => {
                            console.error(err);
                            frappe.msgprint(__('تعذر إنشاء التيكت، تأكد من تعبئة الحقول الإجبارية في مستند HD Ticket.'));
                        });
                        
                    },
                    'إنشاء Ticket جديدة في النظام',
                    'تأكيد الإنشاء'
                );
            });
        }
    },

    // جلب بيانات الـ Opportunity تلقائياً
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frm.set_value('customer', data.customer);
                        frm.set_value('pipeline_am', data.pipeline_am);
                    }
                }
            );
        }
    },

    // تنبيه عند تغيير Status
    status(frm) {
        if (frm.doc.status === 'Completed') {
            frappe.show_alert({
                message: '✅ ممتاز! سيتم تحريك الفرصة إلى Go-Live بعد الحفظ',
                indicator: 'green'
            });
        } else if (frm.doc.status === 'On Hold') {
            frappe.show_alert({
                message: '⏸️ تم تعليق التنفيذ',
                indicator: 'orange'
            });
        }
    }

});

frappe.ui.form.on('Sabre Go-Live', {
    refresh(frm) {
        // تم إزالة شرط الزر هنا بنجاح دون التأثير على تنبيه المتابعة
        if (frm.doc.follow_up_30_days) {
            frappe.show_alert({
                message: `📅 متابعة 30 يوم: ${frm.doc.follow_up_30_days}`,
                indicator: 'blue'
            });
        }
    },
    opportunity(frm) {
        if (frm.doc.opportunity) {
            frappe.db.get_value(
                'Sabre Sales Opportunity',
                frm.doc.opportunity,
                ['customer', 'pipeline_am'],
                (data) => {
                    if (data) {
                        frm.set_value('customer', data.customer);
                        frm.set_value('pipeline_am', data.pipeline_am);
                    }
                }
            );
        }
    },
    status(frm) {
        if (frm.doc.status === 'Won') {
            frappe.show_alert({
                message: '🏆 ممتاز! سيتم إغلاق الفرصة كـ Closed - Won',
                indicator: 'green'
            });
        } else if (frm.doc.status === 'Issues') {
            frappe.show_alert({
                message: '⚠️ سيتم إعادة الفرصة إلى Implementation',
                indicator: 'orange'
            });
        } else if (frm.doc.status === 'Active') {
            frappe.show_alert({
                message: '🚀 الفرصة في مرحلة Go-Live',
                indicator: 'blue'
            });
        }
    },
    go_live_date(frm) {
        if (frm.doc.go_live_date) {
            frappe.show_alert({
                message: '📅 سيتم حساب تواريخ المتابعة تلقائياً عند الحفظ',
                indicator: 'blue'
            });
        }
    }
});

frappe.ui.form.on('Sabre Sales Opportunity', {
    refresh: function(frm) {

        // 1. التحقق من أن المستخدم هو مدير حسابات (AM)
        const is_account_manager = frappe.user_roles.includes('Sabre Account Manager');

        // 2. تحديد الأدوار التي تريد استثناءها تماماً من الملء التلقائي
        const has_excluded_role = frappe.user_roles.includes('Head of Sales') || 
                                  frappe.user_roles.includes('System Manager') 

        // 3. الشرط: يجب أن يكون AM وليس لديه أي دور من الأدوار المستثناة
        if (is_account_manager && !has_excluded_role) {

            // إذا كانت الفرصة جديدة، يتم ملء الحقل تلقائياً
            if (frm.is_new()) {
                frm.set_value('pipeline_am', frappe.session.user);
            }

        }
    }
});

frappe.ui.form.on('Sabre Sales Opportunity', {
    refresh: function(frm) {
        ['total_gds_volume', 'airline_mix', 'sabre_bookings', 'sabre_share',
         'amadeus_bookings', 'travelport_bookings'].forEach(function(f) {
            frm.set_df_property(f, 'read_only', 1);
        });
    },
    customer: function(frm) {
        if (!frm.doc.customer) return;
        frappe.db.get_value('Sabre Agency', frm.doc.customer, 'iata').then(r => {
            if (!r.message || !r.message.iata) {
                frappe.msgprint('This agency has no IATA number.');
                return;
            }
            frappe.call({
                method: 'midt_agency_stats',
                args: { iata: r.message.iata },
                callback: function(res) {
                    let d = res.message;
                    frm.set_value('total_gds_volume', d.total_gds_volume);
                    frm.set_value('airline_mix', d.airline_mix);
                    frm.set_value('sabre_bookings', d.sabre_bookings);
                    frm.set_value('sabre_share', d.sabre_share);
                    frm.set_value('amadeus_bookings', d.amadeus_bookings);
                    frm.set_value('travelport_bookings', d.travelport_bookings);
                    frappe.show_alert('MIDT data loaded: ' + d.total_gds_volume + ' bookings, Sabre share ' + d.sabre_share + '%');
                }
            });
        });
    }
});

frappe.ui.form.on('Sabre Sales Opportunity', {
    refresh: function(frm) {
        if (frm.is_new()) return;
        if (!frappe.user.has_role('Sabre Head Of Sales') && !frappe.user.has_role('System Manager')) return;

        frm.add_custom_button('🔄 Re-assign AM', function() {
            let d = new frappe.ui.Dialog({
                title: 'Re-assign Account Manager',
                fields: [{
                    label: 'New Account Manager',
                    fieldname: 'new_am',
                    fieldtype: 'Link',
                    options: 'User',
                    reqd: 1
                }],
                primary_action_label: 'Re-assign',
                primary_action: function(values) {
                    frappe.call({
                        method: 'reassign_opportunity_am',
                        args: { opportunity: frm.doc.name, new_am: values.new_am },
                        callback: function(r) {
                            d.hide();
                            frappe.show_alert('AM re-assigned to ' + values.new_am);
                            frm.reload_doc();
                        }
                    });
                }
            });
            d.show();
        });
    }
});

frappe.ui.form.on('Sabre Business Case', {
    volume: function(frm) { calc_revenue(frm); },
    rate: function(frm) { calc_revenue(frm); }
});

function calc_revenue(frm) {
    if (frm.doc.volume && frm.doc.rate) {
        frm.set_value('expected_revenue', frm.doc.volume * frm.doc.rate);
    }
}

frappe.ui.form.on('Sabre Business Case', {
    refresh: function(frm) {
        if (frm.is_new()) return;
        if (frm.doc.deal_review_link) {
            frm.add_custom_button(' Open Deal Review Sheet', function() {
                window.open(frm.doc.deal_review_link, '_blank');
            }).addClass('btn-primary');
        }
    }
});
